        self.assertEqual(top_words(""), [])

    def test_basic(self):
        r = top_words("a b a")
        self.assertEqual(r, [("a", 2), ("b", 1)])
        self.assertIsInstance(r, list)
        self.assertIsInstance(r[0], tuple)

    def test_n(self):
        self.assertEqual(top_words("c b a b c c", n=2), [("c", 3), ("b", 2)])

    def test_minlen(self):
        self.assertEqual(top_words("a bb ccc", min_length=2), [("bb", 1), ("ccc", 1)])
        self.assertEqual(top_words("'ab' abc", min_length=3), [("abc", 1)])

    def test_case_apostrophe(self):
        self.assertEqual(top_words("The THE the don't 'tis"),
                         [("the", 3), ("don't", 1), ("tis", 1)])

    def test_underscore_and_apostrophes(self):
        self.assertEqual(top_words("snake_case '''x''' '' a''b a''b"),
                         [("a''b", 2), ("case", 1), ("snake", 1), ("x", 1)])

