        self.assertEqual(len(top_words(" ".join("abcdefghijkl"))), 10)

    def test_bad_n(self):
        with self.assertRaises(ValueError):
            top_words("a", n=0)

    def test_import_no_side_effects(self):
        r = subprocess.run([sys.executable, "-c", "import wordfreq"], cwd=HERE,
                           capture_output=True)
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, b"", b""))


