import unicodedata
import unittest

import wordfreq
from wordfreq import top_words

HERE = os.path.dirname(os.path.abspath(__file__))
SCRIPT = os.path.join(HERE, "wordfreq.py")


def run(text, *args, raw=None):
    with tempfile.NamedTemporaryFile("wb", suffix=".txt", dir=HERE, delete=False) as f:
        f.write(raw if raw is not None else text.encode("utf-8"))
        name = f.name
    try:
        p = subprocess.run([sys.executable, SCRIPT, name, *args],
                           capture_output=True)
    finally:
        os.unlink(name)
    return p.returncode, p.stdout.decode("utf-8"), p.stderr.decode("utf-8")


class CLI(unittest.TestCase):
    def test_e01_case(self):
        self.assertEqual(run("The the THE")[1], "the\t3\n")

    def test_e02_cafe(self):
        self.assertEqual(run("Café café CAFÉ")[1], "café\t3\n")

    def test_e03_nfd(self):
        code, out, _ = run(unicodedata.normalize("NFD", "café"))
        lines = out.splitlines()
        self.assertEqual((code, len(lines)), (0, 1))
        w, c = lines[0].split("\t")
        self.assertEqual((unicodedata.normalize("NFC", w), c), ("café", "1"))

    def test_e04_underscore(self):
        self.assertEqual(run("snake_case")[1], "case\t1\nsnake\t1\n")

    def test_e05_punct(self):
        self.assertEqual(run("a-b,c.d")[1], "a\t1\nb\t1\nc\t1\nd\t1\n")

    def test_e06_strip(self):
        self.assertEqual(run("'tis rock'")[1], "rock\t1\ntis\t1\n")

    def test_e07_internal(self):
        self.assertEqual(run("rock'n'roll")[1], "rock'n'roll\t1\n")

    def test_e08_only_apostrophes(self):
        self.assertEqual(run("'' ''' x")[1], "x\t1\n")

    def test_e08b_many_apostrophes(self):
        self.assertEqual(run("'''x'''")[1], "x\t1\n")

    def test_e09_default_minlen(self):
        self.assertEqual(run("a bb ccc dddd a")[1],
                         "a\t2\nbb\t1\nccc\t1\ndddd\t1\n")

    def test_e10_minlen3(self):
        self.assertEqual(run("a bb ccc dddd a", "--min-length", "3")[1],
                         "ccc\t1\ndddd\t1\n")

    def test_e11_minlen_after_strip(self):
        self.assertEqual(run("'ab' abc", "--min-length", "3")[1], "abc\t1\n")

    def test_e14_default_n(self):
        out = run(" ".join("abcdefghijkl"))[1].splitlines()
        self.assertEqual(out, [f"{c}\t1" for c in "abcdefghij"])

    def test_e15_n_limit(self):
        self.assertEqual(run("a a b c", "-n", "2")[1], "a\t2\nb\t1\n")

    def test_e16_n_bigger(self):
        self.assertEqual(run("a b", "-n", "50")[1], "a\t1\nb\t1\n")

    def test_e17_missing(self):
        p = subprocess.run([sys.executable, SCRIPT, "missing.txt"],
                           capture_output=True, cwd=HERE)
        self.assertEqual(p.returncode, 2)
        self.assertEqual(p.stdout, b"")
        self.assertIn(b"missing.txt", p.stderr)

    def test_e18_n_zero(self):
        code, out, err = run("a b", "-n", "0")
        self.assertEqual((code, out), (2, ""))
        self.assertTrue(err)

    def test_e19_n_negative(self):
        code, out, _ = run("a b", "-n", "-1")
        self.assertEqual((code, out), (2, ""))

    def test_e20_empty(self):
        self.assertEqual(run(""), (0, "", ""))

    def test_e21_only_separators(self):
        self.assertEqual(run("  \n\t ,.;_ \n"), (0, "", ""))

    def test_e22_digits(self):
        self.assertEqual(run("abc123 123abc")[1], "123abc\t1\nabc123\t1\n")

    def test_e23_crlf(self):
        self.assertEqual(run("a\r\nb\r\na\r\n")[1], "a\t2\nb\t1\n")

    def test_e24_combo(self):
        self.assertEqual(run("aa aa bb c c c dd", "-n", "2",
                             "--min-length", "2")[1], "aa\t2\nbb\t1\n")

    def test_e25_leading_zero(self):
        self.assertEqual(run("42 042 42")[1], "42\t2\n042\t1\n")

    def test_e26_greek(self):
        self.assertEqual(run("Ωmega ωMEGA")[1], "ωmega\t2\n")

    def test_e27_double_apostrophe(self):
        self.assertEqual(run("a''b a''b")[1], "a''b\t2\n")

    def test_e33_format(self):
        self.assertEqual(run("a a b"), (0, "a\t2\nb\t1\n", ""))

    def test_sample(self):
        code, out, _ = run("The the THE café 'tis rock'n'roll '' foo_bar")
        self.assertEqual(code, 0)
        self.assertEqual(out.splitlines(),
                         ["the\t3", "bar\t1", "café\t1", "foo\t1",
                          "rock'n'roll\t1", "tis\t1"])

    def test_bad_utf8(self):
        code, out, err = run("", raw=b"\xff\xfe\x00bad")
        self.assertEqual((code, out), (2, ""))
        self.assertIn("wordfreq: error", err)

    def test_tab_stdout_utf8_bytes(self):
        with tempfile.NamedTemporaryFile("wb", suffix=".txt", dir=HERE, delete=False) as f:
            f.write("café".encode("utf-8"))
        try:
            p = subprocess.run([sys.executable, SCRIPT, f.name], capture_output=True)
        finally:
            os.unlink(f.name)
        self.assertEqual(p.stdout, "café\t1\n".encode("utf-8"))


class API(unittest.TestCase):
    def test_e28_empty(self):
        self.assertEqual(top_words(""), [])

    def test_e29_types(self):
        r = top_words("a b a")
        self.assertEqual(r, [("a", 2), ("b", 1)])
        self.assertIsInstance(r, list)
        for w, c in r:
            self.assertIs(type(w), str)
            self.assertIs(type(c), int)
        self.assertIsInstance(r[0], tuple)

    def test_e30_n(self):
        self.assertEqual(top_words("c b a b c c", n=2), [("c", 3), ("b", 2)])

    def test_e31_minlen(self):
        self.assertEqual(top_words("a bb ccc", min_length=2),
                         [("bb", 1), ("ccc", 1)])

    def test_e32_defaults(self):
        self.assertEqual(top_words("The THE the don't 'tis"),
                         [("the", 3), ("don't", 1), ("tis", 1)])

    def test_value_error(self):
        with self.assertRaises(ValueError):
            top_words("a", n=0)

    def test_nfc_merge(self):
        self.assertEqual(top_words("cafe\u0301 caf\u00e9"), [("caf\u00e9", 2)])

    def test_tie_alpha(self):
        self.assertEqual(top_words("b a c"), [("a", 1), ("b", 1), ("c", 1)])

    def test_import_no_side_effects(self):
        self.assertTrue(callable(wordfreq.main))


if __name__ == "__main__":
    unittest.main()
"}

